package com.bank.library;

import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.logging.Logger;

class Book {
    final String isbn, title, author;
    final List<BookItem> copies = new ArrayList<>();
    Book(String isbn, String title, String author) { this.isbn = isbn; this.title = title; this.author = author; }
}

enum ItemStatus { AVAILABLE, ISSUED, RESERVED }

class BookItem {
    final String barcode; ItemStatus status = ItemStatus.AVAILABLE;
    LocalDate dueDate; String memberId;
    BookItem(String barcode) { this.barcode = barcode; }
}

class Member {
    final String id, name; final List<BookItem> issued = new ArrayList<>();
    Member(String id, String name) { this.id = id; this.name = name; }
}

interface FinePolicy { BigDecimal fine(long overdueDays); }
class PerDayFine implements FinePolicy {
    public BigDecimal fine(long days) { return new BigDecimal("10").multiply(BigDecimal.valueOf(Math.max(0, days))); }
}

class Librarian {
    private static final Logger log = Logger.getLogger("LIB");
    private final FinePolicy finePolicy;
    Librarian(FinePolicy fp) { this.finePolicy = fp; }

    BookItem issue(Member m, Book book, LocalDate today) {
        for (BookItem it : book.copies) {
            if (it.status == ItemStatus.AVAILABLE) {
                it.status = ItemStatus.ISSUED; it.memberId = m.id;
                it.dueDate = today.plusDays(14); m.issued.add(it);
                log.info(() -> m.name + " issued " + book.title + " due " + it.dueDate);
                return it;
            }
        }
        throw new IllegalStateException("No copy available for " + book.title);
    }

    BigDecimal returnItem(Member m, BookItem it, LocalDate today) {
        long overdue = Math.max(0, today.toEpochDay() - it.dueDate.toEpochDay());
        it.status = ItemStatus.AVAILABLE; it.memberId = null; m.issued.remove(it);
        BigDecimal fine = finePolicy.fine(overdue);
        log.info(() -> m.name + " returned; overdue=" + overdue + " fine=" + fine);
        return fine;
    }
}

public class LibraryDemo {
    public static void main(String[] args) {
        Book handbook = new Book("978-1", "Banking Compliance Handbook", "RBI");
        handbook.copies.add(new BookItem("BC-1"));
        Member rajesh = new Member("SAV2001", "Rajesh");
        Librarian lib = new Librarian(new PerDayFine());
        BookItem issued = lib.issue(rajesh, handbook, LocalDate.of(2026, 10, 1));
        lib.returnItem(rajesh, issued, LocalDate.of(2026, 10, 18)); // 3 days late
    }
}
